package matrix

import (
	"fmt"
	"strconv"
	"strings"
)

// Matrix is a two-dimensional grid of integers.
type Matrix = *matrix

type matrix struct {
	data [][]int
}

// New parses a string of whitespace-separated numbers, one row per line,
// into a Matrix. It returns an error if any row is empty, rows have
// different lengths, or any token is not a valid integer.
func New(s string) (Matrix, error) {
	lines := strings.Split(s, "\n")
	data := make([][]int, 0, len(lines))
	for i, line := range lines {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, fmt.Errorf("matrix row %d: empty row", i)
		}
		row := make([]int, 0, len(fields))
		for _, f := range fields {
			v, err := strconv.Atoi(f)
			if err != nil {
				return nil, fmt.Errorf("matrix row %d: %q is not an integer", i, f)
			}
			row = append(row, v)
		}
		if len(data) > 0 && len(row) != len(data[0]) {
			return nil, fmt.Errorf("matrix row %d: uneven rows (%d columns, expected %d)", i, len(row), len(data[0]))
		}
		data = append(data, row)
	}
	return &matrix{data: data}, nil
}

// Cols returns the columns of the matrix as an independent copy of the data.
func (m *matrix) Cols() [][]int {
	var n int
	if len(m.data) > 0 {
		n = len(m.data[0])
	}
	cols := make([][]int, n)
	for c := 0; c < n; c++ {
		cols[c] = make([]int, len(m.data))
		for r, row := range m.data {
			cols[c][r] = row[c]
		}
	}
	return cols
}

// Rows returns the rows of the matrix as an independent copy of the data.
func (m *matrix) Rows() [][]int {
	rows := make([][]int, len(m.data))
	for i, row := range m.data {
		rows[i] = make([]int, len(row))
		copy(rows[i], row)
	}
	return rows
}

// Set sets the element at (row, col) to val. It returns false if the
// coordinates are out of range, in which case the matrix is unchanged.
func (m *matrix) Set(row, col, val int) bool {
	if row < 0 || row >= len(m.data) || col < 0 || col >= len(m.data[row]) {
		return false
	}
	m.data[row][col] = val
	return true
}
